  ('0248b070-20b1-414e-8b5a-5c484f308de1', '0ab64115-878e-44b1-b537-cd137443275a', null, 'topic'::public.curated_course_node_type, 'Financial Reporting Purpose, Ethics, Users, Standards, and Information Ecosystem', 'The course begins with why financial reporting exists: to communicate decision-useful information about resources, claims, performance, and cash flows while operating within standards, governance, controls, audits, and ethical duties.', 0),
