  ('78d71683-1e34-4617-b491-5adebeb6914f', '0ab64115-878e-44b1-b537-cd137443275a', null, 'topic'::public.curated_course_node_type, 'Accounting Equation, Business Models, and Linked Financial Statements', 'Students translate economic events and a firm''s business model into the linked statements, then read the statements as one coherent representation rather than four isolated schedules.', 1),
