insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Principles of Accounting, Volume 1: Financial Accounting', 'https://openstax.org/details/books/principles-financial-accounting', 'OpenStax. Free common spine for accounting and non-accounting majors, with practice, examples, and review.', 0),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Financial Accounting (Libby, Libby, and Hodge)', 'McGraw Hill', 'Decision-oriented introduction with strong statement linkage and real-company context.', 1),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Financial Accounting: Tools for Business Decision Making', 'Wiley', 'Kimmel, Weygandt, and Kieso. Accessible mechanics-to-decisions pathway with broad cross-major usability.', 2),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Financial Accounting (Spiceland, Thomas, and Herrmann)', 'McGraw Hill', 'Clear conceptual development and a strong bridge toward intermediate reporting.', 3),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Hospitality Financial Accounting', 'Wiley', 'Weygandt, Kimmel, and Kieso. Industry cases for property, food and beverage, receivables, controls, and operating interpretation.', 4),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Financial Statement Analysis and Security Valuation', 'McGraw Hill', 'Stephen Penman. Selective enrichment for earnings quality, forecasting, profitability, and valuation links.', 5),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Financial Statement Analysis and Valuation', 'Cambridge Business Publishers', 'Easton, McAnally, Sommers, and Zhang. Integrated real-company analysis, forecasting, and valuation bridge.', 6),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'textbook'::public.curated_course_resource_kind, 'Financial Shenanigans', 'McGraw Hill', 'Schilit, Perler, and Engelhart. Case-based identification of earnings, cash-flow, and key-metric manipulation risks.', 7),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'website'::public.curated_course_resource_kind, 'SEC EDGAR Search Filings', 'https://www.sec.gov/search-filings', 'Primary source for 10-Ks, 10-Qs, filing HTML, full-text search, Inline XBRL, and filing APIs.', 8),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'website'::public.curated_course_resource_kind, 'FASB Conceptual Framework', 'https://fasb.org/the-conceptual-framework', 'Objectives, elements, recognition, measurement, presentation, and disclosure concepts.', 9),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'website'::public.curated_course_resource_kind, 'FASB Accounting Standards Codification', 'https://asc.fasb.org', 'Authoritative U.S. GAAP research orientation. Access terms vary.', 10),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'website'::public.curated_course_resource_kind, 'IFRS Accounting Standards and supporting materials', 'https://www.ifrs.org/issued-standards/', 'Authoritative IFRS context, conceptual framework, and implementation support.', 11),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'website'::public.curated_course_resource_kind, 'MIT Sloan 15.515 Financial Accounting', 'https://ocw.mit.edu/courses/15-515-financial-accounting-fall-2003/', 'Lecture notes, problems, annual-report work, and graduate-level case framing.', 12),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'website'::public.curated_course_resource_kind, 'AccountingCoach', 'https://www.accountingcoach.com', 'Short explanations and drills for mechanics. Verify technical conclusions against authoritative guidance.', 13),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'youtube'::public.curated_course_resource_kind, 'Farhat Lectures', 'https://www.youtube.com/@AccountingLectures', 'Long-form worked instruction across financial accounting, reporting, audit, and exam preparation.', 14),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'youtube'::public.curated_course_resource_kind, 'Edspira', 'https://www.youtube.com/@Edspira', 'Concise worked explanations for entries, statements, ratios, and reporting topics.', 15),
  ('0ab64115-878e-44b1-b537-cd137443275a', 'youtube'::public.curated_course_resource_kind, 'Accounting Stuff', 'https://www.youtube.com/@AccountingStuff', 'Beginner-friendly visual explanations useful for pre-class preparation and review.', 16);
